                }

                break;

            case 'minute':
            case 'minutes':
            case 'm':
                $minutes += $intValue;

                if ($fraction) {
                    $parts[] = [null, $fraction * static::getSecondsPerMinute(), 's'];
                }

                break;

            case 'second':
            case 'seconds':
            case 's':
                $seconds += $intValue;

                if ($fraction) {
