private static function copyNegativeUnits(DateInterval $from, DateInterval $to): void
{
    $to->invert = $from->invert;

    foreach (['y', 'm', 'd', 'h', 'i', 's'] as $unit) {
        if ($from->$unit < 0) {
            $to->$unit *= -1;
